StructuredTextModel.Text:
(* 1. Convert raw to mA (diagnostics) *)
rFlow_mA := 4.0 + (DINT_TO_LREAL(An_Flow) / 8400.0) * 16.0;

(* 2. Convert raw to L/min *)
rFlow_LperMin := 0.05 + (DINT_TO_LREAL(An_Flow) / 8400.0) * 1.45;

(* 3. Volume accumulation - sample every 100ms *)
tmrFlowSample(IN := TRUE, PT := tSampleTime);

IF tmrFlowSample.Q THEN
    (* Average flow over sample period (100ms = 0.001667 minutes) *)
    rTotalVolume_L := rTotalVolume_L + ((rFlow_LperMin + rPrevFlow) / 2.0) * 0.001667;
    rPrevFlow := rFlow_LperMin;
    tmrFlowSample(IN := FALSE);
END_IF;
